WaveformRecoveryPanel::~WaveformRecoveryPanel(){delete controls_.data();}
QString WaveformRecoveryPanel::text(const std::string& key,const Json& args) const {Json item={{"label_key",key},{"arguments",args}};catalog_.resolve(item);return localizedText(item.at("label"),language_,QString::fromStdString(key));}
QString WaveformRecoveryPanel::owned(const std::string& key) const {if(key.empty())return {};Json item={{"label_key",key}};const auto domain=result_?result_->resource_namespace:provider_->currentIndex()>=0?recovery_provider(provider_->currentData().toString().toStdString()).resource_namespace:std::string();try{TextCatalog::resource(domain).resolve(item);}catch(...){}return localizedText(item.value("label",Json()),language_,QString::fromStdString(key));}
RecoveryContext WaveformRecoveryPanel::context() const {const auto processed=input_->currentData().toBool();return {processed?processed_:raw_,processed?processedRange_:rawRange_,{},nullptr};}
Json WaveformRecoveryPanel::descriptions(const RecoveryProvider& provider,const Json& values) const {auto fields=provider.describe(context(),values);if(!fields.is_array())throw std::invalid_argument("Recovery parameters must be an array");try{TextCatalog::resource(provider.resource_namespace).resolve(fields);}catch(...){}localize(fields,language_);return fields;}
void WaveformRecoveryPanel::populate(const Json& values){if(refreshing_ || provider_->currentIndex()<0)return;QScopedValueRollback guard(refreshing_,true);try{const auto provider=recovery_provider(provider_->currentData().toString().toStdString());Json about={{"label_key",provider.description_key}};try{TextCatalog::resource(provider.resource_namespace).resolve(about);}catch(...){}about_->setText(localizedText(about.value("label",Json()),language_,QString::fromStdString(provider.description_key)));if(!context().analysis){pendingParameters_=values;return;}parameters_->populate(descriptions(provider,values),values);pendingParameters_.reset();issues_->clear();}catch(...){issues_->setText(text("recovery.error.configuration"));}}
void WaveformRecoveryPanel::refreshDescriptors(){if(refreshing_ || !context().analysis)return;QScopedValueRollback guard(refreshing_,true);try{parameters_->updateDescriptors(descriptions(recovery_provider(provider_->currentData().toString().toStdString()),parameters_->values()));parameters_->showIssues(parameters_->problems());issues_->clear();}catch(...){issues_->setText(text("recovery.error.configuration"));}}
void WaveformRecoveryPanel::setAvailable(bool available){available_=available;apply_->setEnabled(available);exportJson_->setEnabled(available && bool(result_));exportBytes_->setEnabled(available && selectedBytes().has_value());locateInput_->setEnabled(available && !selectedRanges_.empty());locateOriginal_->setEnabled(available && !selectedRanges_.empty());locateOriginal_->setVisible(applied_ && applied_->processed);}
void WaveformRecoveryPanel::setInputs(std::shared_ptr<const WaveformAnalysis> raw,std::shared_ptr<const WaveformAnalysis> processed){raw_=std::move(raw);processed_=std::move(processed);rawRange_=raw_?SignalSampleRange{raw_->first_sample(),raw_->end_sample()-raw_->first_sample()}:SignalSampleRange{};processedRange_=processed_?SignalSampleRange{processed_->first_sample(),processed_->end_sample()-processed_->first_sample()}:SignalSampleRange{};if(pendingParameters_)populate(*pendingParameters_);else if(parameters_->values().empty())populate();else refreshDescriptors();}
void WaveformRecoveryPanel::setSelection(SignalSampleRange raw,SignalSampleRange processed){rawRange_=raw;processedRange_=processed;refreshDescriptors();}
std::optional<WaveformRecoveryRequest> WaveformRecoveryPanel::draft(){if(!enabled_->isChecked())return {};if(!context().analysis)throw std::invalid_argument("Recovery input is unavailable");refreshDescriptors();const auto problems=parameters_->problems();parameters_->showIssues(problems);if(!problems.empty())throw std::invalid_argument("Invalid recovery fields");const auto provider=recovery_provider(provider_->currentData().toString().toStdString());WaveformRecoveryRequest request;request.provider_id=provider.id;request.method_version=provider.method_version;request.parameters=parameters_->values();request.processed=input_->currentData().toBool();request.range=request.processed?processedRange_:rawRange_;return request;}
std::optional<WaveformRecoveryRequest> WaveformRecoveryPanel::readConfiguration(const Json& config){if(config.is_null())return {};if(config.at("version")!=1 && config.at("version")!=2)throw std::invalid_argument("Unsupported recovery configuration");if(!config.at("enabled").get<bool>())return {};WaveformRecoveryRequest request;request.provider_id=config.at("provider_id").get<std::string>();const auto provider=recovery_provider(request.provider_id);if((config.at("version")==1 && provider.protocol_version!=1) || (config.at("version")==2 && config.at("provider_protocol_version")!=provider.protocol_version))throw std::invalid_argument("Recovery provider protocol mismatch");const auto& version=config.at("method_version");if(!version.is_number_integer() || version<1 || version>UINT32_MAX)throw std::invalid_argument("Invalid recovery method version");request.method_version=version.get<unsigned>();request.parameters=config.at("parameters");if(!request.parameters.is_object())throw std::invalid_argument("Invalid recovery parameters");request.processed=config.at("processed").get<bool>();request.budget=readBudget(config.at("budget"));request.range=SignalSampleRange{index(config.at("range").at("first")),index(config.at("range").at("count"))};if(!request.range->count || request.range->first>UINT64_MAX-request.range->count)throw std::invalid_argument("Invalid recovery range");const auto& clock=config.at("input_clock");const auto rate=[&](const char* key){const auto& v=clock.at(key);if(!v.is_number_integer() || v<1 || v>UINT32_MAX)throw std::invalid_argument("Invalid recovery clock");return v.get<std::uint32_t>();};request.expected_clock=SignalSampleClock{index(clock.at("source_origin")),rate("source_rate_hz"),rate("rate_hz")};return request;}
void WaveformRecoveryPanel::restoreDraft(const Json& config){const auto request=readConfiguration(config);if(!request){enabled_->setChecked(false);return;}const QSignalBlocker block(provider_);const auto selected=provider_->findData(QString::fromStdString(request->provider_id));if(selected<0)throw std::invalid_argument("Missing recovery provider");provider_->setCurrentIndex(selected);input_->setCurrentIndex(request->processed?1:0);populate(request->parameters);if(context().analysis && parameters_->values()!=request->parameters)throw std::invalid_argument("Recovery parameters cannot be represented");enabled_->setChecked(true);}
QString WaveformRecoveryPanel::failureText(std::exception_ptr failure,const std::string& fallback){auto message=text(fallback);try{if(failure)std::rethrow_exception(failure);}catch(const RecoveryParameterError& error){auto issues=error.issues;try{TextCatalog::resource(error.resource_namespace).resolve(issues);localize(issues,language_);QStringList lines;std::vector<std::pair<std::string,QString>> fields;for(const auto& issue:issues){const auto line=localizedText(issue.value("label",Json()),language_,message);lines.push_back(line);fields.emplace_back(issue.value("field",std::string()),line);}parameters_->showIssues(fields);if(!lines.empty())message=lines.join(u'\n');}catch(...){}}catch(...){}issues_->setText(message);return message;}
void WaveformRecoveryPanel::showDetails(Json details){if(result_)try{TextCatalog::resource(result_->resource_namespace).resolve(details);localize(details,language_);}catch(...){}details_->setPlainText(QString::fromStdString(details.dump(2)));}
void WaveformRecoveryPanel::setResult(std::shared_ptr<const RecoveryResult> result,std::optional<WaveformRecoveryRequest> request){if(result && (!request || !request->expected_clock || !request->range || request->provider_id!=result->provider_id || request->method_version!=result->method_version || *request->range!=result->range))throw std::invalid_argument("Recovery result lacks its actual request");if(result_==result && result)return;QScopedValueRollback guard(selecting_,true);result_=std::move(result);applied_=std::move(request);selected_.reset();frame_.reset();selectedRanges_.clear();summaries_=Json::array();stages_->clear();checks_->clear();bytes_->clear();sequences_->clear();hexModel_->set({});valueModel_->set({});frameModel_->set({});complex_->set(result_);issues_->clear();
    pages_->setTabVisible(4,result_ && result_->protocol_version>=2);if(!result_){scope_->setText(text("recovery.empty"));selectionLabel_->setText(text("recovery.no_selection"));details_->clear();setAvailable(available_);return;}
    for(unsigned i=0;i<result_->sequences.size();++i){const auto& sequence=result_->sequences[i];sequences_->addItem(owned(sequence.label_key),i);if(sequence.kind==RecoveryValueKind::byte)bytes_->addItem(owned(sequence.label_key),i);const auto known=std::count_if(sequence.values.begin(),sequence.values.end(),[](const auto& value){return value.known;});summaries_.push_back({{"id",sequence.id},{"kind",static_cast<unsigned>(sequence.kind)},{"values",sequence.values.size()},{"known",known}});}
    for(unsigned i=0;i<result_->stages.size();++i){const auto& stage=result_->stages[i];QStringList parents;for(const auto input:stage.inputs)parents.push_back(QString::number(input));auto* item=new QTreeWidgetItem(stages_,{owned(stage.label_key),parents.join(", ")});item->setData(0,Qt::UserRole,i);item->setToolTip(0,QString::fromStdString(stage.id));}
    frameModel_->set(result_);pages_->setTabVisible(0,bytes_->count()>0);pages_->setTabVisible(1,!result_->frames.empty());pages_->setTabVisible(2,sequences_->count()>0);if(bytes_->count())hexModel_->set(result_,bytes_->currentData().toUInt());if(sequences_->count())valueModel_->set(result_,sequences_->currentData().toUInt());
    scope_->setText(text("recovery.scope",{{"provider",owned(recovery_provider(result_->provider_id).label_key).toStdString()},{"source",text(applied_->processed?"channel.tab":"channel.raw_tab").toStdString()},{"frames",result_->frames.size()},{"sequences",result_->sequences.size()}}));scope_->setToolTip(text("recovery.range",{{"first",std::to_string(result_->range.first)},{"count",std::to_string(result_->range.count)}}));
    if(!result_->frames.empty()){showFrame(0);pages_->setCurrentIndex(0);}else {showStage(result_->stages.empty()?-1:0);pages_->setCurrentIndex(bytes_->count()?0:sequences_->count()?2:3);}if(result_->protocol_version>=2)pages_->setCurrentIndex(4);setAvailable(available_);
}
void WaveformRecoveryPanel::showStage(int stage){if(!result_)return;frame_.reset();Json detail={{"event",result_->event},{"method",result_->method},{"input_analysis_method",result_->analysis->method}};if(stage>=0 && static_cast<unsigned>(stage)<result_->stages.size()){const auto& value=result_->stages[static_cast<unsigned>(stage)];detail["stage"]={{"id",value.id},{"label_key",value.label_key},{"inputs",value.inputs},{"parameters",value.parameters},{"features",value.features},{"conclusion",value.conclusion}};}showDetails(std::move(detail));}
